package com.github.alexthe666.rats.server.test;
import com.github.alexthe666.rats.registry.*;
import com.github.alexthe666.rats.server.block.entity.*;
import com.github.alexthe666.rats.server.entity.rat.*;
import com.github.alexthe666.rats.server.inventory.*;
import com.github.alexthe666.rats.server.misc.*;
import com.github.alexthe666.rats.server.storage.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraftforge.gametest.*;
import java.util.UUID;
@GameTestHolder("rats") @PrefixGameTestTemplate(false)
public class Sg16GameTests {
    private static RatFarmingBlockEntity farm(GameTestHelper h){var p=new BlockPos(10,4,20);h.setBlock(p,RatsBlockRegistry.RAT_FARMING.get());var farm=(RatFarmingBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(p));farm.configure(4,16);return farm;}
    private static TamedRat rat(GameTestHelper h){var r=h.spawn(RatsEntityRegistry.TAMED_RAT.get(),new BlockPos(10,5,20));r.setTame(true);r.setNoAi(true);return r;}
    @GameTest(template="quarry_test_empty") public static void squareSizesSourcesAndLegacyRectangle(GameTestHelper h){
        var farm=farm(h);h.assertTrue(farm.layout().width==4&&farm.layout().height==4,"One new size overrides rectangular arguments");
        for(int size=2;size<=16;size++){farm.configure(size,size);var layout=farm.layout();for(int cell=0;cell<256;cell++)if(layout.cropCell(cell)){boolean source=false;for(int w=layout.water.nextSetBit(0);w>=0;w=layout.water.nextSetBit(w+1))if(Math.max(Math.abs(w%16-cell%16),Math.abs(w/16-cell/16))<=3)source=true;h.assertTrue(source,"Every cell within three of a source at size "+size);}}
        var saved=farm.saveWithoutMetadata();saved.putInt("FarmWidth",5);saved.putInt("FarmHeight",7);saved.putInt("FarmLayoutVersion",2);var legacy=new RatFarmingBlockEntity(farm.getBlockPos(),farm.getBlockState());legacy.load(saved);h.assertTrue(legacy.layout().width==5&&legacy.layout().height==7,"Loading old rectangle preserves footprint until explicit reconfiguration");h.succeed();
    }
    @GameTest(template="quarry_test_empty") public static void humidifierHydratesWithoutUpperWaterOrRain(GameTestHelper h){
        var source=h.absolutePos(new BlockPos(8,4,8));var soil=source.offset(3,0,3);h.getLevel().setBlockAndUpdate(source,RatsBlockRegistry.RAT_FARM_LIGHT.get().defaultBlockState());h.getLevel().setBlockAndUpdate(soil.above(3),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(soil,Blocks.FARMLAND.defaultBlockState().setValue(FarmBlock.MOISTURE,0));h.getLevel().getBlockState(soil).randomTick(h.getLevel(),soil,h.getLevel().random);h.assertTrue(h.getLevel().getBlockState(soil).getValue(FarmBlock.MOISTURE)==7,"Real farmland accepts ground lantern source");h.assertTrue(h.getLevel().isEmptyBlock(source.above()),"No extra occupied layer");for(int i=0;i<5;i++)net.minecraft.world.level.material.Fluids.WATER.tick(h.getLevel(),source,h.getLevel().getFluidState(source));h.assertTrue(h.getLevel().getFluidState(source.north()).isEmpty(),"Solid humidifier does not spill water");h.succeed();
    }
    @GameTest(template="quarry_test_empty") public static void farmPausesWhileMenuOpenAndWorksWithoutDirt(GameTestHelper h){
        var f=farm(h);var r=rat(h);r.setItemSlot(EquipmentSlot.CHEST,new ItemStack(RatsItemRegistry.RAT_UPGRADE_FARMER.get()));int[] cells=java.util.stream.IntStream.range(0,256).filter(f.layout()::cropCell).toArray();var usable=f.ground(cells[0]);h.getLevel().setBlockAndUpdate(usable,Blocks.DIRT.defaultBlockState());h.assertTrue(f.taskAt(cells[0],r)!=null&&f.taskAt(cells[1],r)==null&&f.missingDirt(),"Missing dirt skips holes but not viable soil");
        var p=net.minecraftforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"FarmEditing"));h.getLevel().addNewPlayer(p);p.setPos(f.getBlockPos().getCenter());var menu=new RatFarmingMenu(816,p.getInventory(),f);p.containerMenu=menu;h.assertTrue(f.editing()&&f.taskAt(cells[0],r)==null,"Open menu prevents execution");p.containerMenu=p.inventoryMenu;h.assertTrue(!f.editing()&&f.taskAt(cells[0],r)!=null,"Close restores execution without timeout");p.discard();h.succeed();
    }
    @GameTest(template="quarry_test_empty") public static void presetsOverrideAndClearDoesNotConsumeSeeds(GameTestHelper h){var f=farm(h);int cell=java.util.stream.IntStream.range(0,256).filter(f.layout()::cropCell).findFirst().orElseThrow();f.paint(cell,new ItemStack(Items.CARROT));f.template(0,new ItemStack(Items.WHEAT_SEEDS));f.mode(1);h.assertTrue(f.seedAt(cell).is(Items.WHEAT_SEEDS),"Preset overrides custom seed");f.mode(0);h.assertTrue(f.seedAt(cell).isEmpty(),"Old custom mark does not reappear");f.clearPlan();h.assertTrue(f.template(0).isEmpty()&&f.isEmpty(),"Clear deletes only markers");h.succeed();}
    @GameTest(template="quarry_test_empty") public static void storageInitialSnapshotWaitsForActiveMenu(GameTestHelper h){var pos=new BlockPos(8,4,8);h.setBlock(pos,RatsBlockRegistry.RAT_STORAGE_CONTROLLER.get());var c=(RatStorageBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(pos));var p=net.minecraftforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"Snapshot16"));p.setPos(c.getBlockPos().getCenter());c.owner=p.getUUID();var menu=new RatStorageMenu(817,p.getInventory(),c);h.assertTrue(menu.snapshot.isEmpty(),"Constructor does not publish/cache an undeliverable snapshot");p.containerMenu=menu;menu.broadcastChanges();h.assertTrue(menu.snapshot.contains("Workers")&&menu.snapshot.contains("Endpoints"),"First active menu tick sends even unchanged empty network");p.containerMenu=p.inventoryMenu;h.succeed();}
    @GameTest(template="quarry_test_empty") public static void randomRatsAvoidTubesAndWorkersKeepBoundedChunks(GameTestHelper h){var r=rat(h);r.setCommand(RatCommand.WANDER);h.assertTrue(!TubeTravel.authorized(r)&&RatWorkChunks.desired(r).isEmpty(),"Idle unrelated rat has no tube authority or chunk tickets");r.setCommand(RatCommand.HARVEST);h.assertTrue(RatWorkChunks.desired(r).isEmpty(),"Unconfigured harvest rat keeps no chunks");r.setItemSlot(EquipmentSlot.CHEST,new ItemStack(RatsItemRegistry.RAT_UPGRADE_FISHERMAN.get()));h.assertTrue(RatWorkChunks.desired(r).size()==9,"Worker has bounded 3x3 ticking window");RatWorkChunks.update(r);RatWorkChunks.release(r);r.setCommand(RatCommand.SIT);h.assertTrue(RatWorkChunks.desired(r).isEmpty(),"Stopped worker releases desired window");h.succeed();}
    @GameTest(template="quarry_test_empty") public static void fisherProducesActualLoot(GameTestHelper h){var r=rat(h);r.setItemSlot(EquipmentSlot.CHEST,new ItemStack(RatsItemRegistry.RAT_UPGRADE_SILVER_TRAY.get()));var goal=new com.github.alexthe666.rats.server.entity.ai.goal.harvest.RatFishermanGoal(r);for(int i=0;i<5;i++)goal.spawnFishingLoot();h.assertTrue(!r.cargo.isEmpty(),"Real fishing loot parameters yield held items without exception");h.succeed();}
	@GameTest(template="quarry_test_empty",timeoutTicks=3200) public static void fishermanFinishesCastAndDepositsWithoutWatchdogReset(GameTestHelper h){
		for(int x=5;x<=11;x++)for(int z=5;z<=11;z++)h.setBlock(new BlockPos(x,3,z),Blocks.STONE);h.setBlock(new BlockPos(8,3,8),Blocks.WATER);h.setBlock(new BlockPos(6,4,8),Blocks.CHEST);var r=h.spawn(RatsEntityRegistry.TAMED_RAT.get(),new BlockPos(7,4,8));r.setTame(true);r.setItemSlot(EquipmentSlot.CHEST,new ItemStack(RatsItemRegistry.RAT_UPGRADE_FISHERMAN.get()));r.setItemSlot(EquipmentSlot.LEGS,new ItemStack(RatsItemRegistry.RAT_UPGRADE_PLATTER.get()));var chest=h.absolutePos(new BlockPos(6,4,8));r.setDepositPos(GlobalPos.of(h.getLevel().dimension(),chest));r.setCommand(RatCommand.HARVEST);h.succeedWhen(()->{var inventory=StorageRoutes.handler(h.getLevel(),chest,Direction.UP);boolean caught=false;for(int i=0;i<inventory.getSlots();i++)if(!inventory.getStackInSlot(i).isEmpty())caught=true;h.assertTrue(caught,"Real fisherman reaches shore, finishes waiting, and deposits: "+r.getWorkDebugState());r.setCommand(RatCommand.SIT);});
	}
    @GameTest(template="quarry_test_empty") public static void redstoneIsMineralNotBuilding(GameTestHelper h){h.assertTrue(StorageStock.category(new ItemStack(Items.REDSTONE)).equals("minerals"),"Dust tag takes precedence over BlockItem");h.succeed();}
	@GameTest(template="quarry_test_empty") public static void nativeBackpackUpgradeConservesPartialDepositAndRebindsWrapper(GameTestHelper h){
		if(!net.minecraftforge.fml.ModList.get().isLoaded("sophisticatedbackpacks")){h.assertTrue(!(RatsItemRegistry.RAT_STORAGE_BACKPACK_UPGRADE.get() instanceof com.github.alexthe666.rats.server.items.upgrades.BaseRatUpgradeItem),"Optional item is not a rat wearable");h.succeed();return;}
		OptionalBackpackChecks.run(h);
	}
}
